    "creator": {
     "name": "string",
     "email": "user@example.com"
    },
    "members": [
     {
      "name": "string",
      "email": "user@example.com"
     }
    ],
    "invitation_code": "string"
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

